# Fetch all playlists' songs
playlist_songs = {}
all_song_ids = set()
for p in playlists:
    pl = apis.spotify.show_playlist(playlist_id=p['playlist_id'], access_token=spotify_login['access_token'])
    if isinstance(pl, dict) and 'message' in pl:
        print("Error fetching playlist", p['playlist_id'], pl)
        continue
    playlist_songs[p['playlist_id']] = pl['songs']
    for s in pl['songs']:
        all_song_ids.add(s['id'])
print("Total unique song ids:", len(all_song_ids))

